// Balanced reports whether the brackets ()[]{} in s are correctly balanced and nested.
func Balanced(s string) bool {
	stack := make([]rune, 0)
	for _, r := range s {
		switch r {
		case '(', '[', '{':
			stack = append(stack, r)
		case ')':
			if len(stack) == 0 || stack[len(stack)-1] != '(' {
				return false
			}
			stack = stack[:len(stack)-1]
		case ']':
			if len(stack) == 0 || stack[len(stack)-1] != '[' {
				return false
			}
			stack = stack[:len(stack)-1]
		case '}':
			if len(stack) == 0 || stack[len(stack)-1] != '{' {
				return false
			}
			stack = stack[:len(stack)-1]
		default:
			// Ignore other characters.
		}
	}
	return len(stack) == 0
}

func main() {
	fmt.Println(Balanced("()[]{}")) // true
	fmt.Println(Balanced("([)]"))    // false
}

