// Merge returns the merged intervals sorted by start.
func Merge(in [][2]int) [][2]int {
	sort.Slice(in, func(i, j int) bool { return in[i][0] < in[j][0] })
	var out [][2]int
	var start, end int
	for _, i := range in {
		if start == 0 {
			start, end = i[0], i[1]
		} else if i[0] <= end {
			end = max(end, i[1])
		} else {
			out = append(out, [2]int{start, end})
			start, end = i[0], i[1]
		}
	}
	out = append(out, [2]int{start, end})
	return out
}

