// RomanToInt converts a valid uppercase Roman numeral to its integer value.
func RomanToInt(s string) int {
	// Map each Roman numeral to its integer value.
	romanMap := map[rune]int{
		'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
	}

	// Initialize the result.
	result := 0

	// Iterate through the string, converting each Roman numeral to its integer value.
	for i := 0; i < len(s); i++ {
		// Get the value of the current Roman numeral.
		current := romanMap[rune(s[i])]

		// If the next numeral is larger, it's a subtractive pair.
		if i+1 < len(s) && romanMap[rune(s[i+1])] > current {
			result -= current
		} else {
			result += current
		}
	}

	return result
}

