// Decode decodes a run-length encoding like "a3b2c1" into "aaabbc".
func Decode(s string) string {
	var result strings.Builder
	for i := 0; i < len(s); {
		ch := s[i]
		count := 0
		for i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			count = count*10 + int(s[i+1]-'0')
			i++
		}
		result.WriteString(strings.Repeat(string(ch), count+1))
		i++
	}
	return result.String()
}

func main() {
	fmt.Println(Decode("a3b2c1")) // aaabbc
}

