// Caesar shifts each ASCII letter in s by n positions (wrapping within its case).
// Non-letters are unchanged.
func Caesar(s string, n int) string {
	var result []byte
	for _, r := range s {
		if r >= 'a' && r <= 'z' {
			result = append(result, byte((r-'a'+n)%26+'a'))
		} else if r >= 'A' && r <= 'Z' {
			result = append(result, byte((r-'A'+n)%26+'A'))
		} else {
			result = append(result, byte(r))
		}
	}
	return string(result)
}

