// Merge fans-in both inputs into one output channel and closes it when both are closed.
func Merge(a, b <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		for {
			select {
			case v, ok := <-a:
				if !ok {
					close(out)
					return
				}
				out <- v
			case v, ok := <-b:
				if !ok {
					close(out)
					return
				}
				out <- v
			}
		}
	}()
	return out
}

