// TopK returns the k most frequent whitespace-separated words, most frequent first,
// ties broken alphabetically. Words are case-sensitive.
func TopK(s string, k int) []string {
	words := map[string]int{}
	for _, w := range strings.Split(s, " ") {
		words[w]++
	}

	var keys []string
	for k := range words {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if words[keys[i]] == words[keys[j]] {
			return keys[i] < keys[j]
		}
		return words[keys[i]] > words[keys[j]]
	})
	if k > len(words) {
		k = len(words)
	}
	return keys[:k]
}

