// Ring is a fixed-size circular buffer.
type Ring struct {
	data []int
	next int
}

// NewRing creates a new ring of capacity cap.
func NewRing(cap int) *Ring {
	return &Ring{data: make([]int, cap)}
}

// Push appends v to the ring, evicting the oldest value when the buffer is full.
func (r *Ring) Push(v int) {
	r.data[r.next] = v
	r.next = (r.next + 1) % len(r.data)
}

// Items returns the values in the ring, oldest to newest.
func (r *Ring) Items() []int {
	out := make([]int, len(r.data))
	copy(out, r.data)
	return out
}

