// LowerBound returns the index of the FIRST element >= target in sorted s.
// If no element is >= target, it returns len(s).
func LowerBound(s []int, target int) int {
	l, r := 0, len(s)
	for l < r {
		m := (l + r) / 2
		if s[m] < target {
			l = m + 1
		} else {
			r = m
		}
	}
	return l
}

