// Rotate rotates m 90 degrees clockwise in place.
func Rotate(m [][]int) {
	n := len(m)
	for i := 0; i < n/2; i++ {
		for j := i; j < n-i-1; j++ {
			// Store the top element
			top := m[i][j]

			// Move the left element to the top position
			m[i][j] = m[n-j-1][i]

			// Move the bottom element to the left position
			m[n-j-1][i] = m[n-i-1][n-j-1]

			// Move the right element to the bottom position
			m[n-i-1][n-j-1] = m[j][n-i-1]

			// Move the stored top element to the right position
			m[j][n-i-1] = top
		}
	}
}

