// ParseQuery decodes a URL query string into a map of key-value pairs.
// It decodes the values but keeps the keys as-is, keeping duplicates in order.
func ParseQuery(q string) map[string][]string {
	out := make(map[string][]string)
	for _, p := range strings.Split(q, "&") {
		if p == "" {
			continue
		}
		k, v, ok := strings.Cut(p, "=")
		if !ok {
			out[k] = []string{v}
			continue
		}
		out[k] = append(out[k], v)
	}
	return out
}

