// ParallelSum sums nums using exactly `workers` goroutines reading from a shared jobs channel.
func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	var wg sync.WaitGroup
	for _, n := range nums {
		wg.Add(1)
		go func() {
			defer wg.Done()
			jobs <- n
		}()
	}
	wg.Wait()
	close(jobs)
	var total int
	for {
		v, ok := <-jobs
		if !ok {
			break
		}
		total += v
	}
	return total
}

func main() {
	fmt.Println(ParallelSum([]int{1, 2, 3, 4, 5}, 3)) // 15
}

