// IntHeap is a min-heap of ints.
type IntHeap []int

// Len returns the number of elements in the heap.
func (h IntHeap) Len() int { return len(h) }

// Less returns true if the element at index i is less than the element at index j.
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }

// Swap swaps the elements at indices i and j.
func (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push appends v to the end of the heap.
func (h *IntHeap) Push(x any) {
	*h = append(*h, x.(int))
}

// Pop removes and returns the minimum element of the heap.
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// PopAllSorted pops all values from the heap in ascending order.
func PopAllSorted(vals []int) []int {
	h := IntHeap(vals)
	heap.Init(&h)
	var out []int
	for h.Len() > 0 {
		out = append(out, heap.Pop(&h).(int))
	}
	return out
}

