// Chain returns a handler that applies the middlewares in order, with the first
// in the list being the outermost. The handler is the innermost layer.
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
